import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0035 — Barra di stato compatta e opzionale","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0035-status-bar-opzionale.md","filePath":"adr/0035-status-bar-opzionale.md"}'),l={name:"adr/0035-status-bar-opzionale.md"};function n(r,e,s,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0035-—-barra-di-stato-compatta-e-opzionale" tabindex="-1">ADR-0035 — Barra di stato compatta e opzionale <a class="header-anchor" href="#adr-0035-—-barra-di-stato-compatta-e-opzionale" aria-label="Permalink to &quot;ADR-0035 — Barra di stato compatta e opzionale&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.5 (2026-11-02): §2.2.1, §2.6.6, §4.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-30</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga «Word count», <code>statusbar</code>, P0: «Parole, caratteri, selezione»), §4.2 (frontend); V-02/D-01; ADR-0026, ADR-0004</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no rispetto alla v1.1 (che prevede <code>statusbar</code>); precisa ADR-0026 → la riga <code>statusbar</code> di §2.2.1 va scritta come in questo ADR</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>ADR-0026 (M8) ha eliminato la status bar e ha distribuito il contenuto:</p><ul><li>riga/colonna, parole, caratteri e selezione nel pannello <em>Statistiche</em> della sidebar destra;</li><li>indicizzazione, permessi, aggiornamenti, sync e inviti nel footer della sidebar destra, e nell&#39;header a sidebar chiusa.</li></ul><p>Il requisito «Word count» (P0) è soddisfatto dal pannello.</p><p>L&#39;analisi dei gap del 2026-10-30 ha però notato un limite: i conteggi dell&#39;editor si vedono solo con la sidebar destra aperta e sulla tab <em>Statistiche</em>. Chi scrive con un obiettivo di lunghezza, o lavora con la sidebar chiusa per avere spazio (modalità più comune su schermi piccoli e in presentazione), non ha più un&#39;indicazione a colpo d&#39;occhio. Negli editor di note a cui lo spec si ispira, la status bar mostra i conteggi in basso a destra.</p><p>Gli indicatori di stato (sync, permessi, aggiornamenti, inviti) non hanno questo problema: ADR-0026 li porta nell&#39;header quando la sidebar è chiusa.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Barra opzionale, spenta per default.</strong> Il default della shell resta quello di ADR-0026 e del mockup.</p><ul><li><strong>Accensione:</strong><ul><li>impostazione <em>Aspetto › Barra di stato</em> (<code>statusBar</code> in <code>.memobrain/appearance.json</code>, booleano, default <code>false</code>);</li><li>comando <code>app:toggle-status-bar</code>, nella palette, senza hotkey di default;</li><li>chiave del Config Profile <code>appearance.statusBar</code>, che l&#39;amministratore può impostare come default o bloccare, come le altre chiavi di <code>appearance</code>. Va aggiunta alle due copie dello schema.</li></ul></li><li><strong>Posizione:</strong> una riga sottile (circa 22 px) sotto l&#39;area editor, sopra lo slot della chat. Non attraversa le sidebar, quindi non tocca ribbon e footer. Una sola per finestra, riferita al pane attivo.</li><li><strong>Contenuto</strong>, solo informazioni dell&#39;editor attivo, nell&#39;ordine: <ol><li><strong>parole e caratteri</strong> della nota; con una selezione attiva, <strong>parole e caratteri selezionati</strong> al loro posto, come nella riga «Word count» dello spec;</li><li><strong>riga:colonna</strong> del cursore;</li><li><strong>modalità</strong> (Sorgente / Live Preview / Lettura), cliccabile per ciclare, come il comando esistente.</li></ol><ul><li>Su un disegno, un canvas o una base mostra solo il tipo di file. Senza tab attiva è vuota.</li></ul></li><li><strong>Niente duplicati:</strong> sync, permessi, aggiornamenti e inviti non entrano nella barra. Restano nel footer e nell&#39;header (ADR-0026), così c&#39;è una sola fonte per ogni indicatore.</li><li><strong>Dati:</strong> gli stessi del pannello <em>Statistiche</em> (lo store delle statistiche dell&#39;editor, aggiornato con debounce). Nessun binding nuovo, nessun Go.</li><li><strong>Accessibilità:</strong> <code>role=&quot;status&quot;</code> senza <code>aria-live</code>, perché annunciare i conteggi a ogni tasto sarebbe rumore per lo screen reader. La scheda <em>Statistiche</em> (comando <em>Mostra statistiche</em>, <code>sidebar:stats</code>) resta il modo accessibile di ascoltarli. Contrasto conforme a <code>docs/qa/a11y-desktop.md</code>.</li><li><strong>Workbench web:</strong> identico (stesso <code>packages/workbench</code>).</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Ripristinare la status bar di prima di M8, sempre visibile</strong> — scartata: è la barra affollata che ADR-0026 ha eliminato, e duplicherebbe gli indicatori già nel footer e nell&#39;header.</li><li><strong>Conteggi nell&#39;header della nota (sotto il titolo)</strong> — scartata: occupa spazio di contenuto e si confonde con le proprietà.</li><li><strong>Badge sul pulsante della sidebar destra</strong> — scartata: mostra un solo numero e non la selezione.</li><li><strong>Nessuna modifica (solo pannello)</strong> — possibile, ed è lo stato attuale. Questo ADR la supera solo per chi accende la barra: chi non la usa non vede differenze.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Implementazione (2026-11-02):</strong> <code>packages/workbench/src/shell/StatusBar.tsx</code>, montata in <code>shell/VaultView.tsx</code> tra l&#39;area editor e lo slot della chat; impostazione <code>statusBar</code> in <code>state/settings.ts</code> (con la chiave bloccabile in <code>state/managed.ts</code>), comando <code>app:toggle-status-bar</code> nel gruppo <em>view</em> e nel registro di parità (<code>appearance</code>). Parole e caratteri sono quelli del pannello <em>Statistiche</em> (<code>textFigures</code>, senza frontmatter); riga:colonna e selezione vengono dallo store delle statistiche, che ora l&#39;editor riempie anche quando una scheda si apre o un pannello prende il focus (prima solo al primo tasto o movimento del cursore). La modalità cicla Live → Sorgente → Lettura, nell&#39;ordine dei pulsanti della nota.</li><li>La riga <code>statusbar</code> di §2.2.1 dello spec diventa: «Word count — parole, caratteri, selezione nel pannello <em>Statistiche</em>; barra di stato compatta opzionale (spenta per default) con conteggi, posizione e modalità; P0». In §4.2 la barra è descritta in <code>shell/</code>, dove sta il componente, e non in una cartella <code>statusbar/</code> separata.</li><li>Implementazione stimata piccola (un componente in <code>packages/workbench/src/shell/</code>, un&#39;impostazione, un comando, due chiavi i18n, la chiave nello schema). Test: <ul><li>unit (contenuto con e senza selezione, tipi di file);</li><li>e2e su mock (accensione dalla palette e persistenza);</li><li>axe sulla shell con la barra accesa.</li></ul></li><li>Il layout di M8 (<code>docs/qa/m8-shell-ui.md</code>) va verificato anche con la barra accesa: altezza dell&#39;area editor, slot della chat, presentazione Slides (dove la barra si nasconde).</li><li>Se la sperimentazione mostra che quasi tutti la accendono, valutare il default <code>true</code> con un ADR successivo.</li></ul>',15)])])}const g=a(l,[["render",n]]);export{m as __pageData,g as default};
